#include "tca/runtime.h"

template <typename T>
__device__ static __forceinline__ T MmSmallCombine0(T p0, T p1) {
  return (p0 + p1);
}

// MmSmall: launch 128 CTAs x 1024 threads (derived from the loop annotations: gridDim = max over LNTs of CTA LoC products, blockDim = (max warp-K product) x 32 — the runtime validates)
// dynamic SMEM pool: 128 B (v0: disjoint offsets, zero reuse)
namespace {

__global__ void __launch_bounds__(1024) MmSmall(uint32_t M, uint32_t K, uint32_t N, const float* __restrict__ lhs, const float* __restrict__ rhs, float* __restrict__ out) {
  tca::rt::TensorView<const float, 2u> lhs_v(lhs, M, K);
  tca::rt::TensorView<const float, 2u> rhs_v(rhs, K, N);
  tca::rt::TensorView<float, 2u> out_v(out, M, N);
  // dynamic SMEM pool (128 B): one pool, disjoint v0 offsets — the future RA pass overlaps them
  extern __shared__ __align__(16) char tca_smem[];
  tca::rt::Frag<float, 1u, 8u> tca_f0;

  tca::rt::KernelInfo kinfo;
  // LNT #0: M=CTA(T=32,LoC=128) N=sequential(T=256,LoC=1) K=thread/warp(T=256,LoC=32) dim=thread/warp(LoC=1024) dim=sequential(LoC=1) K=sequential(T=256,LoC=1)
  {
    // CTA-space mapping (absolute LoC per dim: 128u — the factorization this nest remaps)
    tca::rt::GridMapping grid_map0(kinfo, 1u, 128u);
    // per-CTA thread-space mapping (absolute warp counts K per dim: 32u)
    tca::rt::ThreadMapping thread_map1(kinfo, 1u, 32u);
    auto c0 = 0.0f;
    auto c1 = 0u;
    auto v0 = M;
    auto c2 = 1u;
    auto v1 = N;
    auto v2 = K;
    auto v3 = grid_map0.index(0u);
    auto c3 = 32u;
    auto v4 = (v3 * c3);
    auto c4 = 256u;
    auto v5 = thread_map1.index(0u);
    auto v6 = (v5 * c4);
    auto v7 = thread_map1.lane_id();
    auto v8 = (v7 + c2);
    auto c5 = 8u;
    auto v9 = (v8 * c5);
    auto v10 = (v7 * c5);
    // warp reduction — the combiner is runtime-owned; per-element brackets [Init → reduced-dim walks (Reduce(value)) → Combine]
    tca::rt::WarpReducer<float> reducer0(c0, MmSmallCombine0, thread_map1, tca::rt::SmemView<float, 1u>(reinterpret_cast<float*>(tca_smem + 0u), 32u));
    // @M tile-between rounds — CTA, T=32, LoC=128 (map dim 0)
    for (auto M_it0 = tca::rt::CtaIterator(grid_map0, 0u, 128u, 0u, 4096u, v0); M_it0.Has(); M_it0.Next()) {
      auto v11 = (v4 + M_it0.Index());
      auto v12 = tca::rt::umin(v11, v0);
      auto v13 = (v0 - v12);
      auto v14 = tca::rt::umin(c3, v13);
      // @N tile-between rounds — sequential, T=256, LoC=1
      for (auto N_it1 = tca::rt::SeqIterator(0u, 256u, v1); N_it1.Has(); N_it1.Next()) {
        auto v15 = tca::rt::umin(N_it1.Index(), v1);
        auto v16 = (v1 - v15);
        auto v17 = tca::rt::umin(c4, v16);
        // @M walk — sequential, LoC=1
        for (auto M_it2 = tca::rt::SeqIterator(0u, 1u, v14); M_it2.Has(); M_it2.Next()) {
          auto v18 = (v11 + M_it2.Index());
          // @N walk — sequential, LoC=1
          for (auto N_it3 = tca::rt::SeqIterator(0u, 1u, v17); N_it3.Has(); N_it3.Next()) {
            // per-element bracket opens (argument-free; re-initializes from the construction-time init)
            reducer0.Init();
            // @K tile-between rounds — thread/warp, T=256, LoC=32 (map dim 0)
            for (auto K_it4 = tca::rt::ThrIterator(thread_map1, 0u, 32u, 0u, 8192u, v2); K_it4.Has(); K_it4.Next()) {
              auto v19 = (v6 + K_it4.Index());
              auto v20 = tca::rt::umin(v19, v2);
              auto v21 = (v2 - v20);
              auto v22 = tca::rt::umin(c4, v21);
              auto v23 = tca::rt::umin(v9, v22);
              auto v24 = (v19 + v10);
              // per-thread tile fill of lhs (LoadTileThread) — no synchronization
              tca::rt::LoadTileThread(thread_map1, tca_f0, tca::rt::TensorWindow(lhs_v, v18, v24));
              // @K inside walk (tile elements) — T=256
              for (auto K_it5 = tca::rt::SeqIterator((v7 * c5), 1u, v23); K_it5.Has(); K_it5.Next()) {
                auto v25 = (v19 + K_it5.Index());
                auto v26 = rhs_v.Get(v25, (N_it1.Index() + N_it3.Index()));
                auto v27 = (K_it5.Index() - v10);
                auto v28 = tca_f0.Get(v27);
                auto v29 = (v28 * v26);
                reducer0.Reduce(v29);
              }
            }
            // per-element combine — every participant receives the element's final value
            auto v30 = reducer0.Combine();
            // single-owner store — the element's owner thread writes (R2/R3)
            if (thread_map1.is_first_in_cta()) {
              out_v.Set(v30, (v11 + M_it2.Index()), (N_it1.Index() + N_it3.Index()));
            }
          }
        }
      }
    }
  }
}

}  // namespace

void MmSmallLaunch(const tca::Tensor<float, 2u>& lhs, const tca::Tensor<float, 2u>& rhs, tca::Tensor<float, 2u>& out, cudaStream_t tca_stream) {
  const uint32_t M = lhs.Dim(0u);
  const uint32_t K = lhs.Dim(1u);
  const uint32_t N = rhs.Dim(1u);
  TCA_REQUIRE(rhs.Dim(0u) == K, "rhs.Dim(0) must equal K (dim K)");
  TCA_REQUIRE(out.Dim(0u) == M, "out.Dim(0) must equal M (dim M)");
  TCA_REQUIRE(out.Dim(1u) == N, "out.Dim(1) must equal N (dim N)");
  tca::rt::ValidateLaunch(dim3(128u, 1u, 1u), dim3(1024u, 1u, 1u), 128u, 512u);
  MmSmall<<<dim3(128u, 1u, 1u), dim3(1024u, 1u, 1u), 128u, tca_stream>>>(M, K, N, lhs.Data(), rhs.Data(), out.Data());
  TCA_CUDA_CHECK(cudaGetLastError());
}
